	(622, 61, NULL, 'Visitor navigated to: http://localhost/harpercollins/index.php', 1, '2026-08-20 13:48:33', '2026-08-20 13:48:33', 0),
	(623, 61, NULL, 'You\'re welcome! I\'m glad I could suggest some books for you. If you have any other questions or need further recommendations, please don\'t hesitate to ask. Otherwise, I hope you find a great book to enjoy!\n\nYou\'re welcome! Let me know if you need anything else.', 0, '2026-08-20 13:48:39', '2026-08-20 13:48:39', 1),
	(624, 61, NULL, 'You\'re welcome! I hope you find a book that interests you. If you have any more questions or need further recommendations, don\'t hesitate to ask. Have a great day!', 0, '2026-08-20 13:48:56', '2026-08-20 13:48:56', 1),
